import React from 'react';
import { LineChart, TrendingUp, BarChart3, Target, ArrowUpRight } from 'lucide-react';

const AnalyticsTab = () => {
  const stats = [
    { label: 'TOTAL_COLLECTED', value: '142.5 Tons', change: '+12%', icon: <BarChart3 className="text-[#CAD23C]" /> },
    { label: 'EFFICIENCY_RATE', value: '94.2%', change: '+2.4%', icon: <Target className="text-[#AB1717]" /> },
    { label: 'ACTIVE_ROUTES', value: '18/20', change: 'Stable', icon: <TrendingUp className="text-[#47510B]" /> },
  ];

  return (
    <div className="w-full animate-slot flex flex-col gap-6">
      {/* ANALYTICS GRID */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className="bg-[#A1AED1] border-[6px] border-[#47510B] p-6 rounded-[30px] shadow-[8px_8px_0_0_#47510B] relative overflow-hidden">
            <div className="flex justify-between items-start mb-4">
              <div className="bg-[#FDFAD8] p-3 rounded-xl border-4 border-[#47510B]">
                {stat.icon}
              </div>
              <span className="text-[10px] font-black bg-[#47510B] text-[#CAD23C] px-2 py-1 rounded italic">LIVE_METRIC</span>
            </div>
            <p className="text-[10px] font-black text-[#47510B] opacity-60 uppercase tracking-widest">{stat.label}</p>
            <div className="flex items-baseline gap-2">
              <h3 className="text-3xl font-[1000] text-[#47510B] italic tracking-tighter">{stat.value}</h3>
              <span className="text-[10px] font-black text-[#AB1717]">{stat.change}</span>
            </div>
          </div>
        ))}
      </div>

      {/* PERFORMANCE CHART PLACEHOLDER */}
      <div className="bg-white border-[8px] border-[#47510B] rounded-[40px] p-8 shadow-2xl">
        <div className="flex items-center justify-between mb-8 border-b-4 border-[#47510B]/10 pb-4">
          <div className="flex items-center gap-3">
            <LineChart className="text-[#AB1717]" />
            <h3 className="text-xl font-black italic text-[#47510B] uppercase">Weekly_Performance_Yield</h3>
          </div>
          <button className="bg-[#47510B] text-[#FDFAD8] text-[10px] font-black px-4 py-2 rounded-xl uppercase hover:bg-[#CAD23C] hover:text-[#47510B] transition-all">
            Export_Report.PDF
          </button>
        </div>

        {/* Visual Mockup for a Graph */}
        <div className="flex items-end gap-2 h-48 px-4">
          {[40, 70, 45, 90, 65, 80, 95].map((h, i) => (
            <div key={i} className="flex-1 flex flex-col items-center gap-2">
              <div 
                className="w-full bg-[#CAD23C] border-x-4 border-t-4 border-[#47510B] rounded-t-lg transition-all hover:bg-[#AB1717]" 
                style={{ height: `${h}%` }}
              />
              <span className="text-[9px] font-black text-[#47510B]">DAY_0{i+1}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default AnalyticsTab;
